package blob

import (
	"bytes"

	"github.com/go-enry/go-enry/v2"
)

// GeneratedKind 는 generated/bundled/vendored 파일 감지 결과의 분류입니다.
//
// 클라이언트가 "왜 미리보기가 disable 되었는지" 친화적 사유를 알 수 있도록
// 카테고리를 분리한다. PreviewState=generated 일 때 PreviewReason 필드에
// HumanReason() 결과를 채운다 (Issue-3144).
//
// 분류 룰의 원천은 GitHub Linguist (go-enry 가 그 데이터를 컴파일하여 제공)
// 이며, 다음 두 함수를 1차 방어선으로 위임한다:
//
//   - enry.IsGenerated(path, content) — `*.min.*`, sourcemap, protobuf
//     codegen, GraphQL codegen, Cargo.lock, package-lock.json 등 generated
//     시그니처. linguist/lib/linguist/generated.rb 룰 셋의 Go 포팅.
//   - enry.IsVendor(path) — `node_modules/`, `vendor/`, `dist/`,
//     `bower_components/` 등 vendored/build-output 경로. 100+개 정규식.
//
// 추가로, 인라인 sourcemap data URI (`//# sourceMappingURL=data:`) 시그니처가
// linguist 룰 보다 빨리 잡히는 케이스가 있어 1순위로 본다 — Issue-3144 의
// 정확한 트리거 패턴이고 linguist 의 IsGenerated 는 파일 전체 sourcemap (.map
// 파일) 만 잡지 source 안의 inline data URI 는 안 잡는다.
type GeneratedKind string

const (
	// GeneratedNone — generated/vendored 아님.
	GeneratedNone GeneratedKind = ""
	// GeneratedSourcemapDataURI — 파일 내 inline sourcemap data URI 발견.
	// 번들러 산출물 (Vite/esbuild/tsc --sourcemap inline) 의 강한 시그니처.
	// linguist 가 못 잡는 케이스이므로 우리가 직접 스캔한다.
	GeneratedSourcemapDataURI GeneratedKind = "sourcemap_data_uri"
	// GeneratedLinguist — enry.IsGenerated() 가 true. 룰은 linguist/
	// generated.rb 에 정의 — minified, codegen 산출물, lockfile 등.
	GeneratedLinguist GeneratedKind = "generated"
	// GeneratedVendored — enry.IsVendor() 가 true. node_modules/, vendor/,
	// dist/ 등 외부 라이브러리 / 빌드 산출물 경로.
	GeneratedVendored GeneratedKind = "vendored"
)

// sourcemapMarkers 는 inline sourcemap data URI 의 시그니처입니다.
// `//# sourceMappingURL=data:` (modern) 또는 `//@ sourceMappingURL=data:`
// (legacy Firefox/Safari) 형태. `data:` 까지 매칭하여 외부 URL 참조는 제외
// (외부 .map 참조는 일반 source 에서도 흔하므로 generated 표시 X).
var sourcemapMarkers = [][]byte{
	[]byte("//# sourceMappingURL=data:"),
	[]byte("//@ sourceMappingURL=data:"),
	[]byte("/*# sourceMappingURL=data:"),
	[]byte("/*@ sourceMappingURL=data:"),
}

// sourcemapTailScanBytes 는 sourcemap 시그니처를 찾을 때 콘텐츠의 끝쪽
// 몇 바이트만 스캔할지 정한다. sourcemap 코멘트는 관습적으로 파일 말미에
// 위치하므로 64KB 윈도우면 충분 + 비용 상한 보장. 시작 부근에 코멘트로
// 'sourcemap' 키워드를 적은 정상 소스의 false positive 도 자연히 피해 간다.
const sourcemapTailScanBytes = 64 * 1024

// DetectGenerated 는 경로와 콘텐츠를 입력받아 generated 분류를 반환합니다.
// 우선순위:
//
//  1. inline sourcemap data URI (Issue-3144 직격 케이스, linguist 미커버)
//  2. enry.IsGenerated — linguist generated.rb 룰
//  3. enry.IsVendor — vendor / build-output 경로
//
// 호출자는 GeneratedNone 이 아니면 PreviewState=generated 로 응답하고
// PreviewReason 에 HumanReason() 결과를 넣는다.
func DetectGenerated(filePath string, content []byte) GeneratedKind {
	// 1. Inline sourcemap data URI — content tail scan.
	scanWindow := content
	if len(scanWindow) > sourcemapTailScanBytes {
		scanWindow = scanWindow[len(scanWindow)-sourcemapTailScanBytes:]
	}
	for _, marker := range sourcemapMarkers {
		if bytes.Contains(scanWindow, marker) {
			return GeneratedSourcemapDataURI
		}
	}

	// 2. Linguist generated heuristic — minified / codegen / lockfile 등.
	// enry 가 path + content 시그니처를 함께 본다.
	if enry.IsGenerated(filePath, content) {
		return GeneratedLinguist
	}

	// 3. Vendored / build-output 경로 — node_modules/, vendor/, dist/ 등.
	if enry.IsVendor(filePath) {
		return GeneratedVendored
	}

	return GeneratedNone
}

// HumanReason 은 GeneratedKind 를 사용자에게 보여줄 사유 문자열로 변환합니다.
// PreviewReason 응답 필드에 사용.
func (k GeneratedKind) HumanReason() string {
	switch k {
	case GeneratedSourcemapDataURI:
		return "File contains an inline source map (generated by a bundler)"
	case GeneratedLinguist:
		return "File is generated (minified, codegen output, or lockfile)"
	case GeneratedVendored:
		return "File is in a vendored or build-output directory"
	default:
		return ""
	}
}
